def all_sizes(folder, path="/"):
    out = {}
    def walk(f, p):
        total = 0
        for name, v in f.items():
            total += walk(v, p + name + "/") if isinstance(v, dict) else v
        out[p] = total
        return total
    walk(folder, path)
    return out

def fib(n, memo=None):
    if memo is None:
        memo = {}
    if n < 2:
        return n
    if n not in memo:
        memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]
